# 3. Examine collision distances in several videos to refine COLL_EPS
import numpy as np

def collision_distances(scope):
    ml_node = _find_node(doc, f"{scope}: Motion log")
    states_by_frame = {}
    for row_index, row in table_rows(ml_node):
        frame = int(row["frame"])
        oid = row["object"].split()[0]
        if frame not in states_by_frame:
            states_by_frame[frame] = {}
        states_by_frame[frame][oid] = {"x": float(row["x"]), "y": float(row["y"])}

    collisions = outcomes(doc, scope)
    dists = []
    for out in collisions:
        if out["kind"] != "collision":
            continue
        t = int(out["time"])
        o1, o2 = out["entities"]
        p1 = states_by_frame.get(t, {}).get(o1)
        p2 = states_by_frame.get(t, {}).get(o2)
        if p1 and p2:
            dx = p1["x"] - p2["x"]
            dy = p1["y"] - p2["y"]
            dists.append((t, (dx*dx+dy*dy)**0.5, (o1,o2)))
    return dists

scopes = ['Video 10119', 'Video 10136', 'Video 10570']
for s in scopes:
