    for d in collision_distances(s):
        print(f"  Frame {d[0]}: {d[2][0]}–{d[2][1]} gap = {d[1]:.3f}")

import math
from collections import defaultdict

# Helper: convert a point+velocity to new position at time t
def update_pos(obj, t):
    dt = t - obj['t']
    obj['x'] += obj['vx'] * dt
    obj['y'] += obj['vy'] * dt
    obj['t'] = t

# Estimate collision time between two moving points (point masses)
def collision_time(obj1, obj2):
    dx = obj1['x'] - obj2['x']
    dy = obj1['y'] - obj2['y']
    dvx = obj1['vx'] - obj2['vx']
    dvy = obj1['vy'] - obj2['vy']
    denom = dvx**2 + dvy**2
    if denom == 0:  # same velocity, never collide
        return None
    t = -(dx*dvx + dy*dvy) / denom
    if t <= 1e-8:  # collision already happened or right now
        return None
    return t

# Simple linear elastic collision: exchange velocities
def resolve_collision(obj1, obj2):
    obj1['vx'], obj2['vx'] = obj2['vx'], obj1['vx']
    obj1['vy'], obj2['vy'] = obj2['vy'], obj1['vy']

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    # Determine simulation bounds
    recorded_end_value = recorded_end(doc, scope)
    if horizon is None:
        horizon = recorded_end_value
    if start is None:
        start = 0.0

    # Sort inputs by time
    inputs_sorted = sorted(inputs, key=lambda r: r['time'])
    # Build a dict of latest state before each time for reconstruction
    latest_state = {}
    for inp in inputs_sorted:
        if inp['kind'] in ('state', 'entry', 'initial_view'):
            for oid in inp['entities']:
                key = (oid, inp['time'])
                latest_state[key] = inp

    # Helper: get latest known state for an entity before given time
    def get_latest_state(oid, t):
        best = None
        for (k_oid, k_t), rec in latest_state.items():
            if k_oid == oid and k_t <= t:
                if best is None or k_t > best[1]:
                    best = (rec, k_t)
        return best[0] if best else None

    # Current entity dict: oid -> {'x','y','vx','vy','t'}
    entities = {}
    # Prepare outputs list
    outcomes = []
    outcome_id = 0

    # Initialize entities at start from latest inputs <= start
    for inp in inputs_sorted:
        if inp['time'] > start: break
        if inp['kind'] == 'state':
            for oid in inp['entities']:
                entities[oid] = {
                    'x': inp['fields']['x'],
                    'y': inp['fields']['y'],
                    'vx': inp['fields']['vx'],
                    'vy': inp['fields']['vy'],
                    't': inp['time']
                }
        elif inp['kind'] == 'entry':
            for oid in inp['entities']:
                # get accompanying state if available at same time
                state_rec = get_latest_state(oid, inp['time'])
                if state_rec and state_rec['kind'] == 'state':
                    entities[oid] = {
                        'x': state_rec['fields']['x'],
                        'y': state_rec['fields']['y'],
                        'vx': state_rec['fields']['vx'],
                        'vy': state_rec['fields']['vy'],
                        't': state_rec['time']
                    }
                else:
                    # default zero velocity
                    entities[oid] = {'x': 0.0, 'y': 0.0,'vx':0.0,'vy':0.0,'t':inp['time']}

    # Simulation loop
    current_time = start
    input_index = 0
    while (horizon is None) or (current_time < horizon):
        # Next input event time
        next_input_time = None
        for j in range(input_index, len(inputs_sorted)):
            if inputs_sorted[j]['time'] > current_time:
                next_input_time = inputs_sorted[j]['time']
                break
        next_event_time = next_input_time if next_input_time is not None else horizon

        while True:
            # Find earliest collision among current entities before next_event_time
            earliest_t = None
            coll_objs = None
            for a_oid, a in list(entities.items()):
                update_pos(a, current_time)  # bring to current time
                for b_oid, b in list(entities.items()):
                    if b_oid <= a_oid:
                        continue
                    update_pos(b, current_time)
                    t_coll_rel = collision_time(a, b)
                    if t_coll_rel is None:
                        continue
                    t_coll_abs = current_time + t_coll_rel
                    if t_coll_abs <= current_time + 1e-8:
                        continue
                    if t_coll_abs <= next_event_time:
                        if earliest_t is None or t_coll_abs < earliest_t:
                            earliest_t = t_coll_abs
                            coll_objs = (a_oid, b_oid)
            if earliest_t is None:
                break
            # Advance all to collision time
            for oid, obj in entities.items():
                update_pos(obj, earliest_t)
            # Resolve collision
            a_oid, b_oid = coll_objs
            a = entities[a_oid]; b = entities[b_oid]
            resolve_collision(a, b)
            # Record outcome
            outcomes.append({
                'id': f'out_{outcome_id}',
                'time': earliest_t,
                'kind': 'collision',
                'entities': [a_oid, b_oid],
                'value': None,
                'src': []  # there is no source in simulation
            })
            outcome_id += 1
            current_time = earliest_t

        # Process next input event
        if next_input_time is None or next_input_time > (horizon if horizon is not None else float('inf')):
            # No more inputs, break after processing collisions
            break
        # Advance all to the time of the input
        for oid, obj in entities.items():
            update_pos(obj, next_input_time)
        current_time = next_input_time
        inp = inputs_sorted[input_index]
        input_index += 1
        if inp['kind'] == 'state':
            for oid in inp['entities']:
                entities[oid] = {
                    'x': inp['fields']['x'],
                    'y': inp['fields']['y'],
                    'vx': inp['fields']['vx'],
                    'vy': inp['fields']['vy'],
                    't': inp['time']
                }
        elif inp['kind'] == 'entry':
            for oid in inp['entities']:
                state_rec = get_latest_state(oid, inp['time'])
                if state_rec and state_rec['kind'] == 'state':
                    entities[oid] = {
                        'x': state_rec['fields']['x'],
                        'y': state_rec['fields']['y'],
                        'vx': state_rec['fields']['vx'],
                        'vy': state_rec['fields']['vy'],
                        't': state_rec['time']
                    }
                else:
                    entities[oid] = {'x': 0.0, 'y': 0.0,'vx':0.0,'vy':0.0,'t':inp['time']}

    return outcomes

